SET NOCOUNT ON;
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
PRINT 'Cód. cliente|Organización|Razón social / Nombre fiscal de la organización|Población|Cód. municipio|Dirección fiscal|Teléfono|E-Mail|NIF|Bloqueado|Obsoleto';
SELECT REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(LTRIM(RTRIM(c.CODCLI)),''),CHAR(9),' '),CHAR(13),' '),CHAR(10),' '),CHAR(124),' '), REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(LTRIM(RTRIM(o.NOMBRE)),''),CHAR(9),' '),CHAR(13),' '),CHAR(10),' '),CHAR(124),' '), REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(LTRIM(RTRIM(o.NOMFISCAL)),''),CHAR(9),' '),CHAR(13),' '),CHAR(10),' '),CHAR(124),' '), REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(LTRIM(RTRIM(ISNULL(NULLIF(LTRIM(RTRIM(o.POBLACION)),''),o.MUNICIPIO))),''),CHAR(9),' '),CHAR(13),' '),CHAR(10),' '),CHAR(124),' '),
REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(LTRIM(RTRIM(ISNULL(NULLIF(LTRIM(RTRIM(o.CODMUNICIPIO)),''),o.CODMUNICIPIOFISCAL))),''),CHAR(9),' '),CHAR(13),' '),CHAR(10),' '),CHAR(124),' '), REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(LTRIM(RTRIM(o.DIRFISCAL)),''),CHAR(9),' '),CHAR(13),' '),CHAR(10),' '),CHAR(124),' '),
REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(LTRIM(RTRIM(CONCAT_WS(' / ',NULLIF(LTRIM(RTRIM(o.TELEFONO)),''),NULLIF(LTRIM(RTRIM(o.TELEFONO2)),''),NULLIF(LTRIM(RTRIM(o.TELEFONOFISCAL)),'')))),''),CHAR(9),' '),CHAR(13),' '),CHAR(10),' '),CHAR(124),' '),
REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(LTRIM(RTRIM(CONCAT_WS(' ; ',NULLIF(LTRIM(RTRIM(o.E_MAIL)),''),NULLIF(LTRIM(RTRIM(o.EMAILFISCAL)),'')))),''),CHAR(9),' '),CHAR(13),' '),CHAR(10),' '),CHAR(124),' '), REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(LTRIM(RTRIM(o.NIF)),''),CHAR(9),' '),CHAR(13),' '),CHAR(10),' '),CHAR(124),' '),
CASE WHEN c.BLOQUEADO='T' OR o.BLOQUEADO_ORG='T' THEN 'Sí' ELSE 'No' END, CASE WHEN o.OBSOLETO='T' THEN 'Sí' ELSE 'No' END
FROM __CLIENTES c JOIN __ORGANIZACION o ON o.IDORG=c.IDORG ORDER BY c.CODCLI;
